<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>Registro de asistencia</title>
<link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.10.0/font/bootstrap-icons.css"><script src="js/theme.js"></script><link rel="stylesheet" href="css/app.css">
<style>
.register{background:#fff;padding:24px;border-radius:12px;overflow:auto;color:#111827}.sheet{min-width:1250px;width:100%;border-collapse:collapse;font-size:.76rem}.sheet th,.sheet td{border:1px solid #8293a0;text-align:center;padding:5px;color:#111827!important}.sheet th{font-weight:800}.sheet .name{text-align:left;min-width:360px;white-space:nowrap}.sheet .code{min-width:125px}.sheet .week{background:#d8eadb;color:#174c2b!important}.sheet .month{background:#e8f1f7;color:#19455e!important}.sheet .day{background:#f4f7f9;color:#243f51!important}.sheet .main{background:#dfe9ee;color:#14394e!important}.sheet .a{background:#e0f3e6;color:#087b46!important;font-weight:900}.sheet .t{background:#fff1d6;color:#a65b00!important;font-weight:900}.sheet .f{background:#fbe3e6;color:#b42335!important;font-weight:900}.title{font-size:1.35rem;font-weight:900;color:#14394e}.meta{display:grid;grid-template-columns:repeat(4,minmax(150px,1fr));gap:10px;margin:18px 0}.meta div{border:1px solid #c9d5dc;border-radius:6px;padding:7px;color:#111827!important}.meta b{color:#14394e}.sticky{position:sticky;left:0;background:#fff;z-index:2}.sheet thead .sticky{background:#dfe9ee;z-index:3}@media print{.sidebar,.no-print{display:none!important}.flex-grow-1{padding:0!important}.register{padding:0}.sheet{min-width:0;font-size:7px}.sheet th,.sheet td{padding:2px}}
</style></head><body class="bg-light"><div class="d-flex"><?php require '../app/views/layouts/sidebar.php'; ?><main class="flex-grow-1 p-4" style="min-height:100vh;overflow:auto">
<div class="d-flex justify-content-between align-items-center mb-4"><div><h2 class="fw-bold mb-1"><i class="bi bi-calendar-check me-2"></i>Registro de asistencia</h2><span class="text-muted">Planilla docente: A = asistió · T = tardanza · F = faltó</span></div></div>
<section class="card border-0 shadow-sm mb-4 no-print"><div class="card-body"><form class="row g-3 align-items-end"><input type="hidden" name="c" value="Report"><input type="hidden" name="a" value="monthly">
<div class="col-lg-2"><label class="form-label">Desde</label><input type="date" class="form-control" name="start_date" value="<?= htmlspecialchars($start) ?>"></div><div class="col-lg-2"><label class="form-label">Hasta</label><input type="date" class="form-control" name="end_date" value="<?= htmlspecialchars($end) ?>"></div>
<div class="col-lg-2"><label class="form-label">Especialidad</label><select class="form-select" name="department_id"><option value="">Todas</option><?php foreach($departments as $d):?><option value="<?= $d['id'] ?>" <?= (string)$filters['department_id']===(string)$d['id']?'selected':'' ?>><?= htmlspecialchars($d['name']) ?></option><?php endforeach;?></select></div>
<div class="col-lg-2"><label class="form-label">Ciclo</label><select class="form-select" name="cycle_id"><option value="">Todos</option><?php foreach($cycles as $c):?><option value="<?= $c['id'] ?>" <?= (string)$filters['cycle_id']===(string)$c['id']?'selected':'' ?>><?= htmlspecialchars($c['name']) ?></option><?php endforeach;?></select></div>
<div class="col-lg-2"><label class="form-label">Semestre</label><select class="form-select" name="semester_id"><option value="">Todos</option><?php foreach($semesters as $s):?><option value="<?= $s['id'] ?>" <?= (string)$filters['semester_id']===(string)$s['id']?'selected':'' ?>><?= htmlspecialchars($s['name']) ?></option><?php endforeach;?></select></div>
<div class="col-lg-1"><label class="form-label">Turno</label><select class="form-select" name="shift"><option value="">Todos</option><option value="manana" <?= $filters['shift']==='manana'?'selected':'' ?>>Mañana</option><option value="tarde" <?= $filters['shift']==='tarde'?'selected':'' ?>>Tarde</option></select></div><div class="col-lg-1"><button class="btn btn-primary w-100">Generar</button></div></form></div></section>
<section class="register shadow-sm"><div class="d-flex justify-content-between align-items-start"><div><div class="title">REGISTRO DE ASISTENCIA</div><small class="text-muted">Período <?= date('d/m/Y',strtotime($start)) ?> — <?= date('d/m/Y',strtotime($end)) ?></small></div><div class="no-print"><a class="btn btn-success btn-sm" href="?c=Report&a=monthlyExport&<?= http_build_query(array_merge($filters,['start_date'=>$start,'end_date'=>$end])) ?>"><i class="bi bi-file-earmark-excel me-1"></i>Exportar a Excel</a></div></div>
<div class="meta"><div><b>Institución:</b> IES José Santos Chocano</div><div><b>Grupo:</b> <?= htmlspecialchars($filters['cycle_id']!==''?'Ciclo seleccionado':'Todos los ciclos') ?></div><div><b>Semestre:</b> <?= htmlspecialchars($filters['semester_id']!==''?'Seleccionado':'Todos') ?></div><div><b>Turno:</b> <?= htmlspecialchars($filters['shift']!==''?ucfirst($filters['shift']):'Todos') ?></div></div>
<table class="sheet"><thead><tr><th rowspan="3" class="main">N.L.</th><th rowspan="3" class="main code">CÓDIGO</th><th rowspan="3" class="main name sticky">NOMBRE DEL ESTUDIANTE</th><?php foreach($weeks as $week):?><th colspan="<?= count($week['days']) ?>" class="week"><?= htmlspecialchars($week['label']) ?></th><?php endforeach;?><th rowspan="3" class="main">FALTAS</th></tr><tr><?php foreach($months as $group):?><th colspan="<?= count($group['days']) ?>" class="month"><?= htmlspecialchars($group['label']) ?></th><?php endforeach;?></tr><tr><?php foreach($days as $day):?><th class="day"><?= date('d',strtotime($day)) ?></th><?php endforeach;?></tr></thead><tbody><?php foreach($students as $i=>$student):$absences=0;?><tr><td><?= $i+1 ?></td><td><?= htmlspecialchars($student['codigo_estudiante']) ?></td><td class="name sticky"><b><?= htmlspecialchars($student['nombre_planilla']) ?></b></td><?php foreach($days as $day):$mark=$attendance[(int)$student['id']][$day] ?? 'F';if($mark==='F')$absences++;?><td class="<?= strtolower($mark) ?>"><?= $mark ?></td><?php endforeach;?><td class="f"><?= $absences ?></td></tr><?php endforeach;?><?php if(!$students):?><tr><td colspan="<?= count($days)+4 ?>" class="p-4">No hay estudiantes para los filtros seleccionados.</td></tr><?php endif;?></tbody></table></section></main></div><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/js/bootstrap.bundle.min.js"></script></body></html>
